function camAt(cx,cy,W,H,dist=14,dx=2,dy=1.8){const K=W/16,x=(cx-W/2)/K,y=(H/2-cy)/K;return[x+dx,y+dy,dist,x,y,0];}
function car3(col){const car=new THREE.Group(),body=new THREE.Mesh(T3.box,mat(col,{metal:0.6,rough:0.25,env:1}));body.scale.set(46,15,30);body.position.y=-14;const cab=new THREE.Mesh(T3.box,mat(0x9fc6ff,{metal:0.2,rough:0.05,opacity:0.6,env:1.2}));cab.scale.set(24,12,26);cab.position.set(-3,-27,0);
  [body,cab].forEach(o=>{o.castShadow=true;car.add(o);});[[22,-15,9],[22,-15,-9]].forEach(([x,y,z])=>{const l=new THREE.Mesh(T3.sph,mat(0xfff4d0,{glow:3}));l.scale.setScalar(3);l.position.set(x,y,z);car.add(l);});
  const wh=[];[[-14,10],[14,10],[-14,-10],[14,-10]].forEach(([x,z])=>{const p=new THREE.Group(),w=new THREE.Mesh(T3.cyl,mat(0x0e1018,{metal:0.3,rough:0.7})),hub=new THREE.Mesh(T3.box,mat(0xdfe6f5,{metal:1,rough:0.2}));w.rotation.x=Math.PI/2;w.scale.set(7,6,7);hub.scale.set(9,2,6.2);w.castShadow=true;p.add(w,hub);p.position.set(x,-6,z+(z>0?6:-6));car.add(p);wh.push(p);});
  car.userData.wh=wh;T3.root.add(car);return car;}
function road3(W,y,depth=110){const r=cube(W*2.2,3,depth,0x161b28,{rough:0.9,metal:0.1});r.position.set(W/2,y+6.5,0);for(let x=-W*0.5;x<W*1.6;x+=46){const d=cube(22,1,4,0xffe9a8,{glow:0.6});d.position.set(x,y+4.8,0);d.castShadow=false;}return r;}
function person3(col){const g=new THREE.Group(),m=mat(col,{metal:0.3,rough:0.4}),sk=mat(0xdfe6f5,{metal:0.2,rough:0.5});const body=new THREE.Mesh(T3.cyl,m);body.scale.set(16,52,12);body.position.y=-74;const head=new THREE.Mesh(T3.sph,sk);head.scale.setScalar(13);head.position.y=-114;
  const legs=[-8,8].map(x=>{const l=new THREE.Mesh(T3.cyl,sk);l.scale.set(5,48,5);l.position.set(x,-24,0);return l;});const arms=[-22,22].map(x=>{const a=new THREE.Mesh(T3.cyl,m);a.scale.set(4.5,40,4.5);a.position.set(x,-78,0);return a;});
  [body,head,...legs,...arms].forEach(o=>{o.castShadow=true;g.add(o);});g.userData.arms=arms;T3.root.add(g);return g;}
function label3(text,col='#dfe7ff',h=22){const c=document.createElement('canvas'),x=c.getContext('2d');x.font='600 44px Inter,system-ui,sans-serif';const w=Math.ceil(x.measureText(text).width)+24;c.width=w;c.height=64;x.font='600 44px Inter,system-ui,sans-serif';x.fillStyle=col;x.textBaseline='middle';x.fillText(text,12,34);
  const t=new THREE.CanvasTexture(c);t.encoding=THREE.sRGBEncoding;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:t,transparent:true,depthWrite:false}));s.scale.set(h*w/64,-h,1);T3.root.add(s);return s;}

