    const seat=new THREE.Mesh(T3.box,mat(0x6a4a2a,{rough:0.6}));seat.scale.set(22,6,4);seat.position.z=10;boat.add(seat);boat.children.forEach(o=>o.traverse(x=>x.castShadow=true));boat.scale.setScalar(1.5);T3.root.add(boat);T3.boat=boat;
